1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.AddressNormalizer;
13	import org.springframework.samples.petclinic.util.LocalityResolver;
14	import org.springframework.samples.petclinic.util.LuhnCheckDigit;
15	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
16	
17	import java.time.Period;
18	import java.util.Collection;
19	import java.util.List;
20	import java.util.Locale;
21	
22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public interface OwnerMapper {
27	
28	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
29	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
30	    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "formatTelephoneDisplay")
31	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "formatCheckDigit")
32	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
33	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "formatMembershipLevel")
34	    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
35	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "formatContactPreference")
36	    @Mapping(target = "ageBand", source = "owner", qualifiedByName = "formatAgeBand")
37	    @Mapping(target = "bulkSignupWarning", ignore = true)
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
42	     * last names, as required by the API's read-only {@code displayName} field.
43	     *
44	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
45	     * applied only where referenced via {@code qualifiedByName}.
46	     */
47	    @Named("formatDisplayName")
48	    default String formatDisplayName(Owner owner) {
49	        if (owner == null) {
50	            return null;
51	        }
52	        return owner.getLastName() + ", " + owner.getFirstName();
53	    }
54	
55	    /**
56	     * Formats an owner's initials as the upper-cased first letters of the first and last
57	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
58	     * API's read-only {@code initials} field.
59	     *
60	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
61	     * applied only where referenced via {@code qualifiedByName}.
62	     */
63	    @Named("formatInitials")
64	    default String formatInitials(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        return initial(owner.getFirstName()) + initial(owner.getLastName());
69	    }
70	
71	    /**
72	     * Formats an owner's stored E.164 telephone for human display, as required by the API's
73	     * read-only {@code telephoneDisplay} field: the country code (with its leading {@code '+'}),
74	     * a space, then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The
75	     * raw {@code telephone} field keeps its canonical E.164 form. Returns {@code null} when no
76	     * telephone is present.
77	     *
78	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
79	     * applied only where referenced via {@code qualifiedByName}.
80	     */
81	    @Named("formatTelephoneDisplay")
82	    default String formatTelephoneDisplay(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
87	    }
88	
89	    /**
90	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
91	     * {@code customerCode} is the owner's {@code '<REGION>-<HASH8>'} customer code and
92	     * {@code YY} is the last two digits of the registration date's year (e.g.
93	     * {@code 'NSW-1A2B3C4D-M26'}), as required by the API's read-only
94	     * {@code membershipNumber} field. Returns {@code null} when either the customer code
95	     * or registration date is absent.
96	     *
97	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
98	     * applied only where referenced via {@code qualifiedByName}.
99	     */
100	    @Named("formatMembershipNumber")
101	    default String formatMembershipNumber(Owner owner) {
102	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
103	            return null;
104	        }
105	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
106	    }
107	
108	    /**
109	     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
110	     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
111	     * code. Returns {@code null} when the customer code is absent.
112	     *
113	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
114	     * applied only where referenced via {@code qualifiedByName}.
115	     */
116	    @Named("formatCheckDigit")
117	    default Integer formatCheckDigit(Owner owner) {
118	        if (owner == null || owner.getCustomerCode() == null) {
119	            return null;
120	        }
121	        return LuhnCheckDigit.compute(owner.getCustomerCode());
122	    }
123	
124	    /**
125	     * Derives an owner's membership level, as required by the API's read-only
126	     * {@code membershipLevel} field: starting at 1, plus 1 when an email address is present,
127	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), capped at 3. (Level 4
128	     * is reserved for tenure.)
129	     *
130	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
131	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
132	     * to record the membership level on the create audit line).
133	     */
134	    @Named("formatMembershipLevel")
135	    default Integer formatMembershipLevel(Owner owner) {
136	        if (owner == null) {
137	            return null;
138	        }
139	        int level = 1;
140	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
141	            level++;
142	        }
143	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
144	            level++;
145	        }
146	        return Math.min(level, 3);
147	    }
148	
149	    /**
150	     * Derives an owner's locality, as required by the API's read-only {@code locality} field:
151	     * the {@code REGION} segment of the owner's {@code '<REGION>-<HASH8>'} customer code, so the
152	     * locality is read from the same region-and-hash identity that the customer code encodes.
153	     * When no customer code is present (e.g. an owner that predates the code), the region is
154	     * resolved directly from the postcode (falling back to the city-to-region table, else
155	     * {@code 'UNKNOWN'}), which yields the same region the code would have carried.
156	     *
157	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
158	     * applied only where referenced via {@code qualifiedByName}.
159	     */
160	    @Named("formatLocality")
161	    default String formatLocality(Owner owner) {
162	        if (owner == null) {
163	            return null;
164	        }
165	        String customerCode = owner.getCustomerCode();
166	        if (customerCode != null) {
167	            int dash = customerCode.indexOf('-');
168	            if (dash > 0) {
169	                return customerCode.substring(0, dash);
170	            }
171	        }
172	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
173	    }
174	
175	    /**
176	     * Derives an owner's preferred contact channel, as required by the API's read-only
177	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
178	     * otherwise {@code 'PHONE'}.
179	     *
180	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
181	     * applied only where referenced via {@code qualifiedByName}.
182	     */
183	    @Named("formatContactPreference")
184	    default String formatContactPreference(Owner owner) {
185	        if (owner == null) {
186	            return null;
187	        }
188	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
189	    }
190	
191	    /**
192	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
193	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
194	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
195	     * no birth date was supplied (so the field is absent), or when no registration date is yet
196	     * known against which to compute the age.
197	     *
198	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
199	     * applied only where referenced via {@code qualifiedByName}.
200	     */
201	    @Named("formatAgeBand")
202	    default String formatAgeBand(Owner owner) {
203	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
204	            return null;
205	        }
206	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
207	        if (age < 18) {
208	            return "MINOR";
209	        }
210	        if (age < 65) {
211	            return "ADULT";
212	        }
213	        return "SENIOR";
214	    }
215	
216	    private static String initial(String name) {
217	        if (name == null || name.isEmpty()) {
218	            return "";
219	        }
220	        return Character.toUpperCase(name.charAt(0)) + ".";
221	    }
222	
223	    Owner toOwner(OwnerDto ownerDto);
224	
225	    @Mapping(target = "id", ignore = true)
226	    @Mapping(target = "pets", ignore = true)
227	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
228	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
229	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
230	    Owner toOwner(OwnerFieldsDto ownerDto);
