248	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
249	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
250	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
251	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
252	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
253	     *
254	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
255	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
256	     *
257	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
258	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
259	     */
260	    @Named("normalizeTelephone")
261	    default String normalizeTelephone(String telephone) {
262	        return TelephoneNormalizer.toE164(telephone);
263	    }
264	
265	    /**
266	     * Normalizes an email address by lower-casing it, so it is stored and returned in a
267	     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
