269	     *
270	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
271	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
272	     * e.g. on update).
273	     */
274	    @Named("normalizeEmail")
275	    default String normalizeEmail(String email) {
276	        return email == null ? null : email.toLowerCase(Locale.ROOT);
277	    }
