285	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
286	        ownerPageDto.setPage(ownerPage.getNumber());
287	        ownerPageDto.setSize(ownerPage.getSize());
288	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
289	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
290	        return ownerPageDto;
291	    }
